Duel.LoadScript("isobar.lua")
local s,id=GetID()
function s.initial_effect(c)
 Xyz.AddProcedure(c,function(tc) return tc:IsLevel(4) and tc:IsRace(RACE_MACHINE) end,4,2); c:EnableReviveLimit()
 local e1=Effect.CreateEffect(c); e1:SetType(EFFECT_TYPE_SINGLE+EFFECT_TYPE_TRIGGER_O); e1:SetProperty(EFFECT_FLAG_DELAY); e1:SetCode(EVENT_SPSUMMON_SUCCESS); e1:SetCountLimit(1,id); e1:SetCondition(function(e) return e:GetHandler():IsSummonType(SUMMON_TYPE_XYZ) and ISOBAR.Field(e:GetHandlerPlayer())~=nil end); e1:SetTarget(function(e,tp,eg,ep,ev,re,r,rp,chk) if chk==0 then return ISOBAR.State(tp)~=ISOBAR.RAIN end end); e1:SetOperation(function(e,tp) ISOBAR.Change(tp,ISOBAR.RAIN,e) end); c:RegisterEffect(e1)
 local e2=Effect.CreateEffect(c); e2:SetType(EFFECT_TYPE_QUICK_O); e2:SetCode(EVENT_CHAINING); e2:SetRange(LOCATION_MZONE); e2:SetCountLimit(1,id+1000); e2:SetCondition(function(e,tp,eg,ep,ev,re,r,rp) return rp==1-tp and ISOBAR.Is(tp,ISOBAR.RAIN) and re:IsActiveType(TYPE_MONSTER) and Duel.IsChainNegatable(ev) end); e2:SetCost(function(e,tp,eg,ep,ev,re,r,rp,chk) if chk==0 then return e:GetHandler():CheckRemoveOverlayCard(tp,1,REASON_COST) end; e:GetHandler():RemoveOverlayCard(tp,1,1,REASON_COST) end); e2:SetTarget(function(e,tp,eg,ep,ev,re,r,rp,chk) if chk==0 then return true end; Duel.SetOperationInfo(0,CATEGORY_DISABLE,eg,1,0,0) end); e2:SetOperation(function(e,tp,eg,ep,ev,re,r,rp) Duel.NegateEffect(ev); local g=Duel.SelectMatchingCard(tp,function(c) return c:IsSetCard(ISOBAR.SET) and c:IsAbleToDeck() end,tp,LOCATION_GRAVE,0,1,1,nil); if #g>0 then Duel.SendtoDeck(g,nil,SEQ_DECKSHUFFLE,REASON_EFFECT) end end); c:RegisterEffect(e2)
end
